const normalizar = (valor) => String(valor ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim()
  .toUpperCase();
const votos = new Map([
  ['RUTA Y COLECTA', 'Ruta y colecta'],
  ['RUTA Y COLECTAS', 'Ruta y colecta'],
  ['RUTA_COLECTA', 'Ruta y colecta'],
  ['RUTA', 'Ruta'],
  ['NO ASISTE', 'No asiste'],
  ['NO ASISTIRE', 'No asiste'],
  ['NO ASISTO', 'No asiste'],
]);
return $input.all().flatMap(({ json }) => {
  const idMotoboy = Number(json.id_motoboy);
  const voto = votos.get(normalizar(json.voto));
  const fechaOperacion = String(json.fecha_operacion ?? '');
  if (!Number.isSafeInteger(idMotoboy) || idMotoboy <= 0 || !voto || !/^\d{4}-\d{2}-\d{2}$/.test(fechaOperacion)) return [];
  return [{ json: {
    idMotoboy,
    voto,
    timestamp: json.vote_timestamp,
    idPoll: json.id_poll || null,
    fechaOperacion,
    fuenteId: json.fuente_id,
  } }];
});
